CREATE COLUMN TABLE "TEST_AP"."AMDR" ("OcrCode" NVARCHAR(8) NOT NULL , "OcrName" NVARCHAR(30), "OcrTotal" DECIMAL(21,6) CS_FIXED, "Direct" NVARCHAR(1) DEFAULT 'N', "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "DimCode" SMALLINT CS_INT DEFAULT 1, "AbsEntry" INTEGER CS_INT, "Active" NVARCHAR(1) DEFAULT 'Y', "logInstanc" INTEGER CS_INT NOT NULL , "UserSign2" SMALLINT CS_INT, "updateDate" LONGDATE CS_LONGDATE, "IsFixedAmt" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("OcrCode", "logInstanc")) UNLOAD PRIORITY 5  AUTO MERGE 